CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'client',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS professionals (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,name TEXT NOT NULL,category TEXT NOT NULL,description TEXT,phone TEXT,latitude REAL,longitude REAL,rating REAL DEFAULT 0,review_count INTEGER DEFAULT 0,plan TEXT DEFAULT 'free',active INTEGER DEFAULT 1,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS services (id INTEGER PRIMARY KEY AUTOINCREMENT,professional_id INTEGER,title TEXT NOT NULL,description TEXT,price_from REAL,FOREIGN KEY(professional_id) REFERENCES professionals(id));
CREATE TABLE IF NOT EXISTS reviews (id INTEGER PRIMARY KEY AUTOINCREMENT,professional_id INTEGER,client_id INTEGER,rating INTEGER NOT NULL,comment TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quote_requests (id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER,category TEXT,description TEXT,latitude REAL,longitude REAL,status TEXT DEFAULT 'open',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS subscriptions (id INTEGER PRIMARY KEY AUTOINCREMENT,professional_id INTEGER,plan TEXT,status TEXT,provider TEXT DEFAULT 'asaas',provider_subscription_id TEXT,expires_at TEXT);
